#[requires(true)]
#[ensures(result@.len() == v1@.len() + v2@.len())]
#[ensures(result@ == v1@ + v2@)]
pub fn append_vectors<T: Copy>(v1: &Vec<T>, v2: &Vec<T>) -> Vec<T> {
    let mut result = Vec::with_capacity(v1.len() + v2.len());
    result.extend_from_slice(v1);
    result.extend_from_slice(v2);
    result
}

