#[requires(first.len() > 0)] 
// drop the last element of `first`, then append all of `second`
#[ensures(result@.len() == (first@.len() - 1) + second@.len())]
#[ensures(result@ == first@.prefix(first@.len() - 1) + second@)]
pub fn replace_last_element(first: &Vec<i32>, second: &Vec<i32>) -> Vec<i32> {
    assert!(!first.is_empty(), "`first` must be non-empty");
    let prefix_len = first.len() - 1;
    let mut result = Vec::with_capacity(prefix_len + second.len());
    result.extend_from_slice(&first[..prefix_len]);
    result.extend_from_slice(second);
    result
}

